title: E-Commerce Platform Architecture
config:
  theme: base
  themeVariables:
    primaryColor: '#e2e8f0'
    edgeLabelBackground: '#ffffff'
    tertiaryColor: '#f8fafc'
---
flowchart TD
    classDef default fill:#f8fafc,stroke:#cbd5e1,stroke-width:1px,color:#334155;
    classDef access fill:#e0f2fe,stroke:#0284c7,stroke-width:2px,color:#0c4a6e;
    classDef business fill:#f3e8ff,stroke:#7e22ce,stroke-width:2px,color:#4c1d95;
    classDef hotspot fill:#fee2e2,stroke:#b91c1c,stroke-width:4px,color:#7f1d1d;
    classDef infra fill:#fef3c7,stroke:#d97706,stroke-width:2px,color:#713f12;
    classDef observe fill:#f1f5f9,stroke:#475569,stroke-width:2px,color:#0f172a,stroke-dasharray: 5 5;
    classDef legendBox fill:#ffffff,stroke:#94a3b8,stroke-width:1px;

    subgraph Access["Access Tier"]
        api-gateway[API Gateway]:::hotspot
        cdn-edge[CDN / Edge Cache]:::access
        auth-service[Auth Service]:::access
        rate-limiter[Rate Limiter]:::access
    end

    subgraph Business["Business Tier"]
        product-catalog[Product Catalog]:::hotspot
        order-service[Order Service]:::hotspot
        payment-service[Payment Service]:::business
        inventory-service[Inventory Service]:::business
        user-profile[User Profile]:::business
        recommendation-engine[Recommendation Engine]:::business
        notification-service[Notification Service]:::business
        search-service[Search Service]:::business
    end

    subgraph Data["Data Tier (Shared Infrastructure)"]
        redis-cache[(Redis Cache)]:::infra
        kafka-mq([Kafka MQ]):::infra
        postgres-primary[(PostgreSQL Primary)]:::infra
        postgres-replica[(PostgreSQL Replica)]:::infra
        elasticsearch[(Elasticsearch)]:::infra
        mongodb[(MongoDB)]:::infra
    end

    subgraph Observability["Observability & Service Mesh (Cross-cutting Overlay)"]
        jaeger-tracing{{Jaeger Tracing}}:::observe
        prometheus{{Prometheus Metrics}}:::observe
        grafana{{Grafana Dashboard}}:::observe
        efk-logging{{EFK Logging Stack}}:::observe
        istio-control{{Istio Control Plane}}:::observe
    end

    subgraph Legend [Visual Encoding Legend]
        direction LR
        l1[Sync Call] -- Solid Line --> l1
        l2[Async / Message Queue] -. Dashed Line .-> l2
        l3[Service Mesh Proxied] == Thick Line ==> l3
        l4[Hotspot Node]:::hotspot
    end
    class Legend legendBox

    cdn-edge -- HTTPS --> api-gateway
    api-gateway == gRPC ==> auth-service
    api-gateway == gRPC ==> rate-limiter
    api-gateway == gRPC ==> product-catalog
    api-gateway == gRPC ==> order-service
    api-gateway == gRPC ==> user-profile
    api-gateway == gRPC ==> search-service
    order-service == gRPC ==> payment-service
    order-service == gRPC ==> inventory-service
    order-service -. Kafka .-> kafka-mq
    payment-service -. Kafka .-> kafka-mq
    kafka-mq -. Kafka .-> notification-service
    kafka-mq -. Kafka .-> inventory-service
    kafka-mq -. Kafka .-> recommendation-engine
    product-catalog == gRPC ==> recommendation-engine
    product-catalog -- Redis --> redis-cache
    product-catalog -- SQL --> postgres-replica
    order-service -- SQL --> postgres-primary
    payment-service -- SQL --> postgres-primary
    inventory-service -- SQL --> postgres-primary
    user-profile -- MongoDB Wire --> mongodb
    user-profile -- Redis --> redis-cache
    recommendation-engine -- MongoDB Wire --> mongodb
    recommendation-engine -- Redis --> redis-cache
    search-service -- REST --> elasticsearch
    search-service -- Redis --> redis-cache
    notification-service -- MongoDB Wire --> mongodb
    auth-service -- Redis --> redis-cache
    auth-service -- SQL --> postgres-replica
    rate-limiter -- Redis --> redis-cache
    postgres-primary -. Streaming Replication .-> postgres-replica
    istio-control -. xDS .-> api-gateway
    istio-control -. xDS .-> product-catalog
    istio-control -. xDS .-> order-service
    istio-control -. xDS .-> payment-service
    istio-control -. xDS .-> inventory-service
    istio-control -. xDS .-> user-profile
    istio-control -. xDS .-> recommendation-engine
    istio-control -. xDS .-> notification-service
    istio-control -. xDS .-> search-service
    istio-control -. xDS .-> auth-service
    jaeger-tracing -- REST --> grafana
    prometheus -- PromQL --> grafana
    efk-logging -- REST --> grafana

